import assert from 'node:assert/strict';
import fs from 'node:fs';
import {spawn,execFileSync} from 'node:child_process';
import {read,json,sha,runGit} from './source-only-backup-20261019.mjs';
const root='F:/VisibleMedicine/staging/20261022-coherent-full-regression';
const sourceReceipt='F:/VisibleMedicine/staging/20261022-review-recovery-website-candidate/VERIFIED_SOURCE.json';
const source=json(sourceReceipt),website=source.website,atlas='F:/VisibleMedicine/atlas';
assert(!fs.existsSync(root),'Create-only regression attempt');
for(const row of source.sourceRows){const bytes=read(website+'/'+row.path);assert.equal(bytes.length,row.bytes,row.path);assert.equal(sha(bytes),row.sha256,row.path);}
assert.equal(source.sourceRows.length,5811);
assert.equal(runGit(['-C',atlas,'rev-parse','HEAD']).toString().trim(),source.source);
