const competing=execFileSync('powershell',['-NoProfile','-Command',"@(Get-CimInstance Win32_Process -Filter \"Name='node.exe'\" | Where-Object {$_.ProcessId -ne "+process.pid+" -and $_.CommandLine -match 'run-website-tests|--test|vinext.*build|typescript/bin/tsc'}).Count"],{encoding:'utf8',windowsHide:true}).trim();
assert.equal(competing,'0','Only one heavy validation job');
fs.mkdirSync(root);
const env={...process.env,VM_ATLAS_SOURCE_REPO:atlas,VM_WEBSITE_ROOT:website,GOMAXPROCS:'2',RAYON_NUM_THREADS:'1',NODE_OPTIONS:'--max-old-space-size=4096'};
const listed=execFileSync(process.execPath,['scripts/run-website-tests.mjs','--list'],{cwd:website,env,encoding:'utf8',windowsHide:true});
fs.writeFileSync(root+'/stock-list.log',listed,{flag:'wx'});
const listedOutput=JSON.parse(listed.trim().split(/\r?\n/).at(-1)).output;
const listing=json(listedOutput+'/manifest.json');
assert.equal(listing.root.replaceAll('\\','/'),website);assert(listing.entryCount>1131);assert.equal(listing.entryCount,listing.entries.length);
const prepared={at:new Date().toISOString(),website,atlas,source:source.source,review:source.review,sourceReceipt,sourceReceiptSha256:sha(read(sourceReceipt)),closedCandidatePaths:5811,entryCount:listing.entryCount,namedTestInputs:listing.files.length,entrySha256:listing.entrySha256,sourceSha256:listing.sourceSha256,stockListManifest:listedOutput+'/manifest.json',stockListManifestSha256:sha(read(listedOutput+'/manifest.json')),oldInterruptedAttemptNotResumed:true,passingClaim:false,ownerPreviewChanged:false};
fs.writeFileSync(root+'/PREPARED.json',JSON.stringify(prepared,null,2)+'\n',{flag:'wx'});
const runs=website+'/.local/website-test-runs',before=new Set(fs.readdirSync(runs));
const log=root+'/driver.log',fd=fs.openSync(log,'wx');
const child=spawn(process.execPath,['scripts/run-website-tests.mjs','--run'],{cwd:website,env,windowsHide:true,stdio:['ignore',fd,fd]});
const kickoff={...prepared,at:new Date().toISOString(),driverPid:process.pid,runnerPid:child.pid,command:'node scripts/run-website-tests.mjs --run',log,terminal:false};
fs.writeFileSync(root+'/DRIVER_STARTED.json',JSON.stringify(kickoff,null,2)+'\n',{flag:'wx'});
const pointer=json('CURRENT_CHECKPOINT.json');
pointer.activeWork.previousInterruptedFullAssurance=pointer.activeWork.runningFullAssurance;
pointer.activeWork.runningFullAssurance={...kickoff,root,live:true,session:null,passingClaim:false,next:'Observe this exact live attempt, not the old interrupted baseline. Keep all5811 source paths frozen and run no other heavy job. Do not restart on silence or claim partial progress markers as totals. Advance independent source-isolated work while it runs; retain every diagnostic and source epoch.'};
pointer.activeWork.inflight.heavyJobRunning=true;pointer.activeWork.inflight.runningSession=null;pointer.activeWork.inflight.runningDriver='run-coherent-full-regression-20261022.mjs';pointer.activeWork.inflight.runningStage=root;pointer.activeWork.updated=kickoff.at;
fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(pointer,null,2)+'\n');
console.log(JSON.stringify(kickoff));
const result=await new Promise(resolve=>{child.once('error',error=>resolve({code:1,error:String(error)}));child.once('close',(code,signal)=>resolve({code,signal}));});fs.closeSync(fd);
const created=fs.readdirSync(runs).filter(name=>!before.has(name));
let terminal={...kickoff,at:new Date().toISOString(),terminal:true,result,created,logSha256:sha(read(log)),passingClaim:false,suiteCompleted:false};
if(created.length===1&&fs.existsSync(runs+'/'+created[0]+'/receipt.json')){
 const output=runs+'/'+created[0],manifest=json(output+'/manifest.json'),receipt=json(output+'/receipt.json');
 assert.deepEqual(manifest.entries,listing.entries);assert.deepEqual(manifest.files,listing.files);assert.equal(manifest.sourceSha256,listing.sourceSha256);
 terminal={...terminal,output,manifest:output+'/manifest.json',manifestSha256:sha(read(output+'/manifest.json')),receipt:output+'/receipt.json',receiptSha256:sha(read(output+'/receipt.json')),counts:receipt.counts,testInputDrift:receipt.testInputDrift,publicPreviewAssetDrift:receipt.publicPreviewAssetDrift,passingClaim:receipt.passingClaim,unskippedPassingClaim:receipt.unskippedPassingClaim,suiteCompleted:true};
}
terminal.closedSourceDrift=source.sourceRows.filter(row=>sha(read(website+'/'+row.path))!==row.sha256).map(row=>row.path);
assert.equal(terminal.closedSourceDrift.length,0);
fs.writeFileSync(root+'/TERMINAL.json',JSON.stringify(terminal,null,2)+'\n',{flag:'wx'});
const completedPointer=json('CURRENT_CHECKPOINT.json');
assert.equal(completedPointer.activeWork.runningFullAssurance.root,root);
Object.assign(completedPointer.activeWork.runningFullAssurance,{...terminal,live:false,terminalReceipt:root+'/TERMINAL.json',terminalReceiptSha256:sha(read(root+'/TERMINAL.json')),next:'Classify actual complete-run failures and coverage limits against preserved baselines before selecting repairs. Do not discard assertions, replace historical sources with current bytes or claim clinical/release approval.'});
completedPointer.activeWork.inflight.heavyJobRunning=false;completedPointer.activeWork.inflight.runningSession=null;completedPointer.activeWork.inflight.runningDriver=null;completedPointer.activeWork.inflight.runningStage=null;completedPointer.activeWork.updated=terminal.at;
fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(completedPointer,null,2)+'\n');
console.log(JSON.stringify({terminal:true,code:result.code,output:terminal.output,counts:terminal.counts,testInputDrift:terminal.testInputDrift,closedSourceDrift:terminal.closedSourceDrift,passingClaim:terminal.passingClaim}));
process.exitCode=result.code??1;
